<?php
declare(strict_types=1);

if (is_file(__DIR__.'/enterprise_v800.php')) require_once __DIR__.'/enterprise_v800.php';
if (is_file(__DIR__.'/ai_orchestrator_v710.php')) require_once __DIR__.'/ai_orchestrator_v710.php';

function v900_tid(): int { if(isset($GLOBALS['V900_TENANT_OVERRIDE'])) return (int)$GLOBALS['V900_TENANT_OVERRIDE']; if(isset($GLOBALS['V800_TENANT_OVERRIDE'])) return (int)$GLOBALS['V800_TENANT_OVERRIDE']; return function_exists('tenant_id')?(int)tenant_id():0; }
function v900_user(): ?array { return function_exists('current_user')?current_user():null; }
function v900_table(string $table): bool { static $c=[]; if(isset($c[$table]))return $c[$table]; if(!preg_match('/^[A-Za-z0-9_]+$/',$table))return false; try{$q=db()->prepare('SHOW TABLES LIKE ?');$q->execute([$table]);return $c[$table]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$table]=false;} }
function v900_cols(string $table): array { static $c=[];if(isset($c[$table]))return $c[$table];if(!v900_table($table))return $c[$table]=[];try{$q=db()->query('SHOW COLUMNS FROM `'.str_replace('`','',$table).'`');$o=[];foreach($q->fetchAll()?:[] as $r)$o[(string)$r['Field']]=true;return $c[$table]=$o;}catch(Throwable $e){return $c[$table]=[];} }
function v900_json($v,array $default=[]): array { if(is_array($v))return $v;$j=json_decode((string)$v,true);return is_array($j)?$j:$default; }
function v900_clip(string $v,int $max=1000): string {$v=trim($v);return mb_strlen($v)>$max?mb_substr($v,0,$max).'…':$v;}
function v900_uuid(string $prefix=''): string {return $prefix.bin2hex(random_bytes(8)).'-'.bin2hex(random_bytes(4));}
function v900_rows(string $table,string $where='1=1',array $params=[],string $order='id DESC',int $limit=100): array {if(!v900_table($table)||!preg_match('/^[A-Za-z0-9_]+$/',$table))return [];try{$sql="SELECT * FROM `{$table}` WHERE tenant_id=? AND {$where} ORDER BY {$order} LIMIT ".max(1,min(500,$limit));$q=db()->prepare($sql);$q->execute(array_merge([v900_tid()],$params));return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function v900_count(string $table,string $where='1=1',array $params=[]): int {if(!v900_table($table)||!preg_match('/^[A-Za-z0-9_]+$/',$table))return 0;try{$q=db()->prepare("SELECT COUNT(*) FROM `{$table}` WHERE tenant_id=? AND {$where}");$q->execute(array_merge([v900_tid()],$params));return (int)$q->fetchColumn();}catch(Throwable $e){return 0;} }
function v900_sum(string $table,string $column,string $where='1=1',array $params=[]): float {if(!v900_table($table)||!preg_match('/^[A-Za-z0-9_]+$/',$table)||!preg_match('/^[A-Za-z0-9_]+$/',$column))return 0;try{$q=db()->prepare("SELECT COALESCE(SUM(`{$column}`),0) FROM `{$table}` WHERE tenant_id=? AND {$where}");$q->execute(array_merge([v900_tid()],$params));return (float)$q->fetchColumn();}catch(Throwable $e){return 0;} }
function v900_settings(bool $refresh=false): array {static $c=null;if($refresh)$c=null;if($c!==null)return $c;if(!v900_table('enterprise_settings_v900'))return $c=[];try{$q=db()->prepare('SELECT settings_json FROM enterprise_settings_v900 WHERE tenant_id=? LIMIT 1');$q->execute([v900_tid()]);return $c=v900_json($q->fetchColumn()?:'');}catch(Throwable $e){return $c=[];}}
function v900_setting(string $key,$default=null){$s=v900_settings();return array_key_exists($key,$s)?$s[$key]:(function_exists('v800_setting')?v800_setting($key,$default):(function_exists('setting')?setting($key,$default):$default));}
function v900_save_settings(array $patch,?int $by=null): void {$s=v900_settings();foreach($patch as $k=>$v)$s[(string)$k]=$v;db()->prepare('INSERT INTO enterprise_settings_v900(tenant_id,settings_json,updated_by,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE settings_json=VALUES(settings_json),updated_by=VALUES(updated_by),updated_at=NOW()')->execute([v900_tid(),json_encode($s,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$by]);v900_settings(true);}
function v900_encrypt(string $v): string {if($v==='')return '';if(function_exists('v800_encrypt'))return v800_encrypt($v);if(function_exists('ai710_encrypt'))return ai710_encrypt($v);throw new RuntimeException('Encrypted secret vault is unavailable.');}
function v900_decrypt(?string $v): string {if(!$v)return '';if(function_exists('v800_decrypt'))return v800_decrypt($v);return function_exists('ai710_decrypt')?ai710_decrypt($v):'';}
function v900_hint(string $v): string {if(function_exists('v800_hint'))return v800_hint($v);$n=strlen($v);return $n<8?'••••':substr($v,0,3).'…'.substr($v,-4);}
function v900_ip_hash(): ?string {$ip=(string)($_SERVER['REMOTE_ADDR']??'');return $ip===''?null:hash('sha256',v900_tid().'|'.$ip);}
function v900_rate_limit(string $scope,int $limit,int $windowSeconds): bool {if(!v900_table('api_rate_limits_v900'))return true;$limit=max(1,$limit);$windowSeconds=max(30,$windowSeconds);$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');$bucket=hash('sha256',v900_tid().'|'.$scope.'|'.$ip);try{db()->beginTransaction();$q=db()->prepare('SELECT hit_count,window_started_at FROM api_rate_limits_v900 WHERE bucket_key=? FOR UPDATE');$q->execute([$bucket]);$r=$q->fetch();$reset=!$r||strtotime((string)$r['window_started_at'])<=time()-$windowSeconds;if($reset){db()->prepare('INSERT INTO api_rate_limits_v900(bucket_key,tenant_id,hit_count,window_started_at,updated_at) VALUES(?,?,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id),hit_count=1,window_started_at=NOW(),updated_at=NOW()')->execute([$bucket,v900_tid()]);$allowed=true;}else{$hits=(int)$r['hit_count']+1;db()->prepare('UPDATE api_rate_limits_v900 SET hit_count=?,updated_at=NOW() WHERE bucket_key=?')->execute([$hits,$bucket]);$allowed=$hits<=$limit;}db()->commit();return $allowed;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();return true;}}
function v900_audit(string $module,string $action,string $summary,string $risk='low',?string $etype=null,?int $eid=null,array $meta=[]): void {if(!v900_table('audit_events_v900'))return;$u=v900_user();$ua=(string)($_SERVER['HTTP_USER_AGENT']??'');try{db()->prepare('INSERT INTO audit_events_v900(tenant_id,actor_user_id,module_key,action_key,entity_type,entity_id,risk_level,summary,ip_hash,user_agent_hash,meta_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([v900_tid(),$u?(int)$u['id']:null,$module,$action,$etype,$eid,$risk,v900_clip($summary,1000),v900_ip_hash(),$ua!==''?hash('sha256',$ua):null,$meta?json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);}catch(Throwable $e){} }

function v900_dashboard_stats(): array {
    return [
        'devices'=>v900_count('mobile_devices_v900','enabled=1'),
        'push_pending'=>v900_count('mobile_push_queue_v900',"status IN ('pending','retry')"),
        'inbox_open'=>v900_count('comm_conversations_v900',"status IN ('open','pending')"),
        'messages_30d'=>v900_count('comm_messages_v900','created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)'),
        'settlement_due'=>v900_sum('settlement_batches_v900','net_amount',"status IN ('approved','processing')"),
        'invoices_due'=>v900_sum('billing_invoices_v900','total_amount',"status IN ('issued','overdue')")-v900_sum('billing_invoices_v900','paid_amount',"status IN ('issued','overdue')"),
        'kyc_pending'=>v900_count('kyc_profiles_v900',"status IN ('pending','under_review')"),
        'workflows'=>v900_count('automation_workflows_v900','enabled=1'),
        'workflow_runs_30d'=>v900_count('automation_runs_v900','created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)'),
        'crm_open'=>v900_count('crm_contacts_v900',"stage NOT IN ('won','lost','archived')"),
        'tickets_open'=>v900_count('helpdesk_tickets_v900',"status NOT IN ('resolved','closed')"),
        'employees'=>v900_count('hr_employees_v900',"status='active'"),
        'vendors'=>v900_count('procurement_vendors_v900',"status='active'"),
        'compliance_due'=>v900_count('compliance_controls_v900',"status='active' AND next_review_at IS NOT NULL AND next_review_at<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)"),
    ];
}

function v900_mobile_branding(): array {if(!v900_table('mobile_branding_v900'))return [];try{$q=db()->prepare('SELECT * FROM mobile_branding_v900 WHERE tenant_id=? LIMIT 1');$q->execute([v900_tid()]);return $q->fetch()?:[];}catch(Throwable $e){return [];}}
function v900_mobile_version(string $platform): ?array {if(!v900_table('mobile_app_versions_v900'))return null;try{$q=db()->prepare('SELECT * FROM mobile_app_versions_v900 WHERE tenant_id=? AND platform=? AND enabled=1 ORDER BY build_number DESC,id DESC LIMIT 1');$q->execute([v900_tid(),$platform]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function v900_mobile_device_upsert(array $in,?int $userId=null): int {$uuid=v900_clip((string)($in['device_uuid']??''),190);if($uuid===''||strlen($uuid)<8)throw new RuntimeException('A stable device_uuid is required.');$platform=in_array((string)($in['platform']??''),['android','ios','web'],true)?(string)$in['platform']:'android';$push=v900_clip((string)($in['push_token']??''),8000);$prov=v900_clip((string)($in['push_provider']??''),30);db()->prepare('INSERT INTO mobile_devices_v900(tenant_id,user_id,device_uuid,platform,push_provider,push_token,app_version,build_number,locale,timezone,last_ip_hash,last_seen_at,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW(),1,NOW(),NOW()) ON DUPLICATE KEY UPDATE user_id=COALESCE(VALUES(user_id),user_id),platform=VALUES(platform),push_provider=VALUES(push_provider),push_token=IF(VALUES(push_token)<>\'\',VALUES(push_token),push_token),app_version=VALUES(app_version),build_number=VALUES(build_number),locale=VALUES(locale),timezone=VALUES(timezone),last_ip_hash=VALUES(last_ip_hash),last_seen_at=NOW(),enabled=1,updated_at=NOW()')->execute([v900_tid(),$userId,$uuid,$platform,$prov?:null,$push?:null,v900_clip((string)($in['app_version']??''),40)?:null,isset($in['build_number'])?(int)$in['build_number']:null,v900_clip((string)($in['locale']??''),20)?:null,v900_clip((string)($in['timezone']??''),80)?:null,v900_ip_hash()]);$q=db()->prepare('SELECT id FROM mobile_devices_v900 WHERE tenant_id=? AND device_uuid=? LIMIT 1');$q->execute([v900_tid(),$uuid]);return (int)$q->fetchColumn();}
function v900_mobile_issue_token(int $userId,?int $deviceId=null,array $scopes=['mobile']): string {$token=bin2hex(random_bytes(32));$days=max(1,min(365,(int)v900_setting('mobile_session_days',30)));db()->prepare('INSERT INTO mobile_sessions_v900(tenant_id,user_id,device_id,token_hash,token_hint,scopes_json,expires_at,created_at) VALUES(?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL '.$days.' DAY),NOW())')->execute([v900_tid(),$userId,$deviceId,hash('sha256',$token),substr($token,0,5).'…'.substr($token,-5),json_encode(array_values(array_unique($scopes)))]);return $token;}
function v900_mobile_auth(?string $token=null): ?array {$token=$token??(preg_match('/^Bearer\s+(.+)$/i',(string)($_SERVER['HTTP_AUTHORIZATION']??''),$m)?trim($m[1]):'');if($token==='')return null;try{$q=db()->prepare('SELECT * FROM mobile_sessions_v900 WHERE token_hash=? AND revoked_at IS NULL AND expires_at>NOW() LIMIT 1');$q->execute([hash('sha256',$token)]);$s=$q->fetch();if(!$s)return null;$GLOBALS['V900_TENANT_OVERRIDE']=(int)$s['tenant_id'];db()->prepare('UPDATE mobile_sessions_v900 SET last_used_at=NOW() WHERE id=?')->execute([(int)$s['id']]);return $s;}catch(Throwable $e){return null;}}
function v900_user_login(string $login,string $password): ?array {if(!v900_table('users'))return null;$cols=v900_cols('users');$where=[];$p=[];foreach(['email','username','phone'] as $c)if(isset($cols[$c])){$where[]="`{$c}`=?";$p[]=$login;}if(!$where)return null;try{$sql='SELECT * FROM users WHERE ('.implode(' OR ',$where).')';if(isset($cols['tenant_id'])&&v900_tid()>0){$sql.=' AND tenant_id=?';$p[]=v900_tid();}$sql.=' LIMIT 1';$q=db()->prepare($sql);$q->execute($p);$u=$q->fetch();if(!$u)return null;$hash=(string)($u['password_hash']??$u['password']??'');if($hash===''||!password_verify($password,$hash))return null;if(isset($u['status'])&&!in_array((string)$u['status'],['active','1','approved'],true))return null;return $u;}catch(Throwable $e){return null;}}
function v900_public_snapshot(int $limit=60): array {$tid=v900_tid();$out=['generated_at'=>date('c'),'tenant_id'=>$tid,'businesses'=>[],'content'=>[],'news'=>[]];$defs=[['businesses','businesses'],['city_portal_items','content'],['news','news']];foreach($defs as [$t,$key]){if(!v900_table($t))continue;$c=v900_cols($t);$fields=[];foreach(['id','name','title','slug','category','content_type','short_description','description','address','city','latitude','longitude','image','image_url','status','created_at','updated_at'] as $f)if(isset($c[$f]))$fields[]='`'.$f.'`';if(!$fields)continue;$where=[];$p=[];if(isset($c['tenant_id'])){$where[]='tenant_id=?';$p[]=$tid;}if(isset($c['status']))$where[]="status IN ('active','published','approved','1')";$sql='SELECT '.implode(',',$fields).' FROM `'.$t.'`'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.(isset($c['updated_at'])?'updated_at DESC':(isset($c['id'])?'id DESC':'1')).' LIMIT '.max(1,min(100,$limit));try{$q=db()->prepare($sql);$q->execute($p);$rows=$q->fetchAll()?:[];foreach($rows as &$r){if(isset($r['description']))$r['description']=v900_clip(strip_tags((string)$r['description']),600);}unset($r);$out[$key]=$rows;}catch(Throwable $e){}}return $out;}
function v900_realtime_emit(string $event,array $payload=[],string $channel='public',?int $userId=null,int $ttlMinutes=1440): int {$ttlMinutes=max(5,min(10080,$ttlMinutes));if(!v900_table('mobile_realtime_events_v900'))return 0;db()->prepare('INSERT INTO mobile_realtime_events_v900(tenant_id,user_id,channel_key,event_key,payload_json,expires_at,created_at) VALUES(?,?,?,?,?,DATE_ADD(NOW(),INTERVAL '.$ttlMinutes.' MINUTE),NOW())')->execute([v900_tid(),$userId,$channel,$event,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return (int)db()->lastInsertId();}
function v900_realtime_poll(int $afterId,string $channel='public',?int $userId=null,int $limit=100): array {if(!v900_table('mobile_realtime_events_v900'))return [];try{$sql='SELECT id,channel_key,event_key,payload_json,created_at FROM mobile_realtime_events_v900 WHERE tenant_id=? AND id>? AND (expires_at IS NULL OR expires_at>NOW()) AND (channel_key=?'.($userId?' OR user_id=?':'').') ORDER BY id ASC LIMIT '.max(1,min(200,$limit));$p=[v900_tid(),max(0,$afterId),$channel];if($userId)$p[]=$userId;$q=db()->prepare($sql);$q->execute($p);$rows=$q->fetchAll()?:[];foreach($rows as &$r)$r['payload']=v900_json($r['payload_json']??'');return $rows;}catch(Throwable $e){return [];}}
function v900_deep_link(string $code): ?array {try{$q=db()->prepare('SELECT * FROM mobile_deep_links_v900 WHERE tenant_id=? AND code=? AND enabled=1 LIMIT 1');$q->execute([v900_tid(),$code]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}

function v900_http(string $url,array $headers=[],?array $json=null,int $timeout=25,?array $basic=null): array {if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Invalid HTTPS endpoint.');$parts=parse_url($url);if(strtolower((string)($parts['scheme']??''))!=='https' && !in_array((string)($parts['host']??''),['127.0.0.1','localhost'],true))throw new RuntimeException('HTTPS is required for external API calls.');$ch=curl_init($url);$h=array_merge(['Accept: application/json'], $headers);if($json!==null){$h[]='Content-Type: application/json';curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($json,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$h,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>max(5,min(60,$timeout)),CURLOPT_FOLLOWLOCATION=>false]);if($basic)curl_setopt($ch,CURLOPT_USERPWD,$basic[0].':'.$basic[1]);$body=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false)throw new RuntimeException($err?:'HTTP request failed.');$data=json_decode((string)$body,true);if($code<200||$code>=300)throw new RuntimeException('Provider HTTP '.$code.': '.v900_clip(is_array($data)?json_encode($data):$body,500));return ['code'=>$code,'data'=>is_array($data)?$data:['raw'=>(string)$body]];}
function v900_push_profile(?int $id=null): ?array {$rows=v900_rows('mobile_push_profiles_v900','enabled=1',[],'is_default DESC,id DESC',30);if($id)foreach($rows as $r)if((int)$r['id']===$id)return $r;return $rows[0]??null;}
function v900_push_queue(string $title,string $body,?int $userId=null,?int $deviceId=null,string $deepLink='',array $data=[]): int {db()->prepare("INSERT INTO mobile_push_queue_v900(tenant_id,user_id,device_id,title,body,deep_link,data_json,status,available_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'pending',NOW(),NOW(),NOW())")->execute([v900_tid(),$userId,$deviceId,v900_clip($title,220),v900_clip($body,4000),$deepLink?:null,$data?json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);return (int)db()->lastInsertId();}
function v900_push_send_row(array $row): string {$profile=v900_push_profile(isset($row['profile_id'])?(int)$row['profile_id']:null);if(!$profile)throw new RuntimeException('No enabled push provider profile.');$type=(string)$profile['provider_type'];$secret=v900_decrypt((string)$profile['secret_cipher']);$cfg=v900_json($profile['config_json']??'');$devices=[];if(!empty($row['device_id']))$devices=v900_rows('mobile_devices_v900','id=? AND enabled=1',[(int)$row['device_id']],'id',5);elseif(!empty($row['user_id']))$devices=v900_rows('mobile_devices_v900','user_id=? AND enabled=1',[(int)$row['user_id']],'id',500);else{try{$q=db()->prepare("SELECT id,push_token,push_provider FROM mobile_devices_v900 WHERE tenant_id=? AND enabled=1 AND push_token IS NOT NULL AND push_token<>'' ORDER BY id");$q->execute([v900_tid()]);$devices=$q->fetchAll()?:[];}catch(Throwable $e){$devices=[];}}$tokens=array_values(array_unique(array_filter(array_map(fn($d)=>(string)($d['push_token']??''),$devices))));if(!$tokens)throw new RuntimeException('No registered push tokens matched this notification.');$payloadData=v900_json($row['data_json']??'');$msgid='';if($type==='onesignal'){$url=(string)($profile['endpoint_url']?:'https://api.onesignal.com/notifications');$payload=['app_id'=>(string)$profile['app_id'],'include_subscription_ids'=>$tokens,'headings'=>['en'=>(string)$row['title']],'contents'=>['en'=>(string)$row['body']],'data'=>$payloadData];if(!empty($row['deep_link']))$payload['url']=(string)$row['deep_link'];$ids=[];foreach(array_chunk($tokens,2000) as $chunk){$payload['include_subscription_ids']=$chunk;$res=v900_http($url,['Authorization: Key '.$secret],$payload);$ids[]=(string)($res['data']['id']??'onesignal');}$msgid=implode(',',$ids);}
    elseif($type==='fcm_v1'){$url=(string)$profile['endpoint_url'];if($url==='')throw new RuntimeException('FCM HTTP v1 endpoint is required.');$sent=0;foreach($tokens as $token){$payload=['message'=>['token'=>$token,'notification'=>['title'=>(string)$row['title'],'body'=>(string)$row['body']],'data'=>array_map('strval',$payloadData)]];v900_http($url,['Authorization: Bearer '.$secret],$payload);$sent++;}$msgid='fcm:'.$sent;}
    else {$url=(string)$profile['endpoint_url'];if($url==='')throw new RuntimeException('Generic push endpoint is required.');$res=v900_http($url,$secret!==''?['Authorization: Bearer '.$secret]:[],['tokens'=>$tokens,'title'=>(string)$row['title'],'body'=>(string)$row['body'],'deep_link'=>$row['deep_link'],'data'=>$payloadData]);$msgid=(string)($res['data']['id']??'generic');}
    return $msgid;
}

function v900_sender_profile(?int $id=null,string $channel=''): ?array {$where='enabled=1';$p=[];if($channel!==''){$where.=' AND channel=?';$p[]=$channel;}$rows=v900_rows('comm_sender_profiles_v900',$where,$p,'is_default DESC,id DESC',50);if($id)foreach($rows as $r)if((int)$r['id']===$id)return $r;return $rows[0]??null;}
function v900_comm_conversation(string $channel,string $address,?int $profileId=null,?string $externalThread=null,?string $name=null): int {$externalThread=$externalThread?:$address;try{$q=db()->prepare('SELECT id FROM comm_conversations_v900 WHERE tenant_id=? AND channel=? AND external_thread_id=? ORDER BY id DESC LIMIT 1');$q->execute([v900_tid(),$channel,$externalThread]);$id=(int)($q->fetchColumn()?:0);if($id)return $id;db()->prepare("INSERT INTO comm_conversations_v900(tenant_id,channel,sender_profile_id,external_thread_id,contact_name,contact_address,status,unread_count,last_message_at,created_at,updated_at) VALUES(?,?,?,?,?,?,'open',0,NOW(),NOW(),NOW())")->execute([v900_tid(),$channel,$profileId,$externalThread,$name,$address]);return (int)db()->lastInsertId();}catch(Throwable $e){throw new RuntimeException('Unable to open conversation.');}}
function v900_comm_queue(int $conversationId,string $body,?int $profileId=null,?string $subject=null,bool $ai=false,?int $campaignId=null): int {db()->prepare("INSERT INTO comm_messages_v900(tenant_id,conversation_id,campaign_id,direction,sender_profile_id,subject,body,status,ai_generated,created_at,updated_at) VALUES(?,?,?,'outbound',?,?,?,'queued',?,NOW(),NOW())")->execute([v900_tid(),$conversationId,$campaignId,$profileId,$subject,v900_clip($body,20000),$ai?1:0]);db()->prepare('UPDATE comm_conversations_v900 SET last_message_at=NOW(),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([v900_tid(),$conversationId]);return (int)db()->lastInsertId();}
function v900_comm_inbound(int $profileId,string $from,string $body,string $externalMessageId='',string $externalThreadId='',?string $name=null,array $meta=[]): int {$p=v900_sender_profile($profileId);if(!$p)throw new RuntimeException('Sender profile unavailable.');$cid=v900_comm_conversation((string)$p['channel'],$from,$profileId,$externalThreadId?:$from,$name);db()->prepare("INSERT INTO comm_messages_v900(tenant_id,conversation_id,direction,sender_profile_id,external_message_id,body,status,meta_json,delivered_at,created_at,updated_at) VALUES(?,?,'inbound',?,?,?,'delivered',?,NOW(),NOW(),NOW())")->execute([v900_tid(),$cid,$profileId,$externalMessageId?:null,v900_clip($body,20000),$meta?json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);$mid=(int)db()->lastInsertId();db()->prepare('UPDATE comm_conversations_v900 SET unread_count=unread_count+1,last_message_at=NOW(),updated_at=NOW() WHERE id=? AND tenant_id=?')->execute([$cid,v900_tid()]);v900_realtime_emit('message.received',['conversation_id'=>$cid,'message_id'=>$mid], 'inbox');if(!empty($p['ai_auto_reply'])&&function_exists('ai710_chat')){try{$GLOBALS['V800_TENANT_OVERRIDE']=v900_tid();$r=ai710_chat($body,null,null,'comm-'.$cid);$reply=trim((string)($r['reply']??$r['text']??''));if($reply!=='')v900_comm_queue($cid,$reply,$profileId,null,true);}catch(Throwable $e){}}return $mid;}
function v900_comm_send_row(array $m): string {$q=db()->prepare('SELECT c.*,m.sender_profile_id mid_profile FROM comm_conversations_v900 c JOIN comm_messages_v900 m ON m.conversation_id=c.id WHERE m.id=? AND m.tenant_id=? LIMIT 1');$q->execute([(int)$m['id'],v900_tid()]);$c=$q->fetch();if(!$c)throw new RuntimeException('Conversation not found.');$p=v900_sender_profile((int)($m['sender_profile_id']?:$c['sender_profile_id']),(string)$c['channel']);if(!$p)throw new RuntimeException('No sender profile is enabled for this channel.');$secret=v900_decrypt((string)$p['secret_cipher']);$cfg=v900_json($p['config_json']??'');$to=(string)$c['contact_address'];$channel=(string)$p['channel'];$provider=(string)$p['provider_type'];if($channel==='whatsapp'&&$provider==='meta_cloud'){$phoneId=(string)($cfg['phone_number_id']??$p['account_ref']??'');$ver=(string)($cfg['api_version']??'v21.0');if($phoneId==='')throw new RuntimeException('WhatsApp phone_number_id is missing.');$url=(string)($p['endpoint_url']?:('https://graph.facebook.com/'.$ver.'/'.$phoneId.'/messages'));$res=v900_http($url,['Authorization: Bearer '.$secret],['messaging_product'=>'whatsapp','to'=>$to,'type'=>'text','text'=>['body'=>(string)$m['body']]]);return (string)($res['data']['messages'][0]['id']??'whatsapp');}
    if($channel==='sms'&&$provider==='twilio'){$sid=(string)$p['account_ref'];$url=(string)($p['endpoint_url']?:('https://api.twilio.com/2010-04-01/Accounts/'.rawurlencode($sid).'/Messages.json'));$ch=curl_init($url);$post=http_build_query(['To'=>$to,'From'=>(string)$p['sender_identity'],'Body'=>(string)$m['body']]);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_USERPWD=>$sid.':'.$secret,CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false||$code<200||$code>=300)throw new RuntimeException($err?:'Twilio SMS HTTP '.$code);$j=json_decode((string)$raw,true);return (string)($j['sid']??'twilio');}
    if($channel==='email'){$toEmail=filter_var($to,FILTER_VALIDATE_EMAIL)?$to:'';if($toEmail==='')throw new RuntimeException('Valid recipient email is required.');$subject=(string)($m['subject']?:v900_setting('email_default_subject','ShahkotPK Notification'));$mailer=__DIR__.'/mailer.php';if(is_file($mailer))require_once $mailer;if(function_exists('smtp_send_mail')){smtp_send_mail($toEmail,$subject,nl2br(htmlspecialchars((string)$m['body'],ENT_QUOTES,'UTF-8')),(string)$m['body']);return 'smtp:'.bin2hex(random_bytes(6));}if(!@mail($toEmail,$subject,(string)$m['body']))throw new RuntimeException('No working SMTP/PHP mail transport is available.');return 'mail:'.bin2hex(random_bytes(6));}
    if($channel==='in_app'){$uid=(int)($c['user_id']?:$to);if($uid<1)throw new RuntimeException('In-app messaging requires a user ID as the recipient address.');$eid=v900_realtime_emit('in_app.message',['conversation_id'=>(int)$c['id'],'message_id'=>(int)$m['id'],'subject'=>$m['subject'],'body'=>$m['body']],'user',$uid,10080);return 'inapp:'.$eid;}
    $url=(string)$p['endpoint_url'];if($url==='')throw new RuntimeException('Provider endpoint is missing.');$headers=$secret!==''?['Authorization: Bearer '.$secret]:[];$res=v900_http($url,$headers,['to'=>$to,'from'=>$p['sender_identity'],'subject'=>$m['subject'],'body'=>$m['body'],'channel'=>$channel]);return (string)($res['data']['id']??$res['data']['message_id']??'custom');}
function v900_delivery_event(string $external,string $event,array $payload=[]): void {if($external==='')return;$map=['sent'=>'sent','delivered'=>'delivered','read'=>'read','failed'=>'failed'];$status=$map[$event]??$event;try{$q=db()->prepare('SELECT id FROM comm_messages_v900 WHERE tenant_id=? AND external_message_id=? ORDER BY id DESC LIMIT 1');$q->execute([v900_tid(),$external]);$mid=(int)($q->fetchColumn()?:0);db()->prepare('INSERT INTO comm_delivery_events_v900(tenant_id,message_id,external_message_id,event_type,provider_status,payload_json,occurred_at) VALUES(?,?,?,?,?,?,NOW())')->execute([v900_tid(),$mid?:null,$external,$event,$status,$payload?json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);if($mid&&isset($map[$event])){$col=$event==='delivered'?'delivered_at':($event==='read'?'read_at':($event==='failed'?'failed_at':'sent_at'));db()->exec("UPDATE comm_messages_v900 SET status=".db()->quote($status).",`{$col}`=COALESCE(`{$col}`,NOW()),updated_at=NOW() WHERE id=".$mid);}}catch(Throwable $e){} }

function v900_campaign_expand(array $campaign): int {$aud=v900_json($campaign['audience_json']??'');$recipients=$aud['recipients']??[];if(!is_array($recipients))$recipients=[];$profile=v900_sender_profile((int)($campaign['sender_profile_id']??0),(string)$campaign['channel']);if(!$profile)throw new RuntimeException('Campaign sender profile is unavailable.');$n=0;foreach(array_slice($recipients,0,5000) as $r){$address=trim(is_array($r)?(string)($r['address']??''):(string)$r);if($address==='')continue;$name=is_array($r)?(string)($r['name']??''):null;$cid=v900_comm_conversation((string)$campaign['channel'],$address,(int)$profile['id'],$address,$name?:null);v900_comm_queue($cid,(string)($campaign['body']??''),(int)$profile['id'],(string)($campaign['subject']??''),false,(int)$campaign['id']);$n++;}db()->prepare("UPDATE comm_campaigns_v900 SET status='processing',total_count=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$n,(int)$campaign['id'],v900_tid()]);return $n;}
function v900_campaign_schedule(string $name,string $channel,int $profileId,string $body,array $recipients,string $subject='',?string $scheduleAt=null): int {db()->prepare("INSERT INTO comm_campaigns_v900(tenant_id,name,channel,sender_profile_id,audience_json,subject,body,schedule_at,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?, 'scheduled',?,NOW(),NOW())")->execute([v900_tid(),$name,$channel,$profileId,json_encode(['recipients'=>$recipients],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$subject?:null,$body,$scheduleAt?:date('Y-m-d H:i:s'),v900_user()['id']??null]);return (int)db()->lastInsertId();}
function v900_settlement_create(string $type,string $payeeType,int $payeeId,float $gross,string $module='marketplace'): int {if($gross<=0)throw new RuntimeException('Settlement gross amount must be positive.');$commission=v900_commission($module,$gross,$payeeType);$net=round($gross-$commission,2);if($net<0)throw new RuntimeException('Commission exceeds gross settlement amount.');$no='SET-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$u=v900_user();db()->beginTransaction();try{db()->prepare("INSERT INTO settlement_batches_v900(tenant_id,batch_no,settlement_type,gross_amount,commission_amount,net_amount,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,'draft',?,NOW(),NOW())")->execute([v900_tid(),$no,$type,$gross,$commission,$net,$u?(int)$u['id']:null]);$bid=(int)db()->lastInsertId();db()->prepare("INSERT INTO settlement_items_v900(tenant_id,batch_id,payee_type,payee_id,source_type,gross_amount,commission_amount,net_amount,status,created_at) VALUES(?,?,?,?,?,?,?,?,'pending',NOW())")->execute([v900_tid(),$bid,$payeeType,$payeeId,$module,$gross,$commission,$net]);db()->commit();v900_audit('settlements','batch_created','Settlement '.$no.' created.','high','settlement_batch',$bid,['payee_type'=>$payeeType,'payee_id'=>$payeeId,'gross'=>$gross,'net'=>$net]);return $bid;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
function v900_settlement_status(int $id,string $status): void {if(!in_array($status,['draft','approved','processing','paid','failed','cancelled'],true))throw new RuntimeException('Invalid settlement status.');$u=v900_user();db()->prepare("UPDATE settlement_batches_v900 SET status=?,approved_by=IF(?='approved',?,approved_by),approved_at=IF(?='approved',NOW(),approved_at),paid_at=IF(?='paid',NOW(),paid_at),updated_at=NOW() WHERE tenant_id=? AND id=?")->execute([$status,$status,$u?(int)$u['id']:null,$status,$status,v900_tid(),$id]);db()->prepare('UPDATE settlement_items_v900 SET status=? WHERE tenant_id=? AND batch_id=?')->execute([$status==='paid'?'paid':($status==='cancelled'?'cancelled':'pending'),v900_tid(),$id]);v900_audit('settlements','status_changed','Settlement status changed to '.$status.'.','high','settlement_batch',$id);if($status==='paid')v900_emit_event('settlement.paid','settlement_batch',$id,[]);}
function v900_subscription_create(string $type,int $id,string $plan,float $amount,string $interval='monthly',?int $gatewayId=null): int {if($id<1||$plan===''||$amount<0)throw new RuntimeException('Valid subscriber, plan and amount are required.');$next=$interval==='annual'?'+1 year':($interval==='weekly'?'+1 week':'+1 month');db()->prepare("INSERT INTO billing_subscriptions_v900(tenant_id,subscriber_type,subscriber_id,plan_key,amount,currency,interval_key,status,starts_at,renews_at,auto_renew,gateway_id,created_at,updated_at) VALUES(?,?,?,?,?,'PKR',?,'active',NOW(),?,1,?,NOW(),NOW())")->execute([v900_tid(),$type,$id,$plan,$amount,$interval,date('Y-m-d H:i:s',strtotime($next)),$gatewayId]);return (int)db()->lastInsertId();}
function v900_refund_create(?int $txId,float $amount,string $reason): int {if($amount<=0)throw new RuntimeException('Refund amount must be positive.');$no='REF-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$u=v900_user();db()->prepare("INSERT INTO billing_refunds_v900(tenant_id,transaction_id,refund_no,amount,reason,status,requested_by,created_at) VALUES(?,?,?,?,?,'requested',?,NOW())")->execute([v900_tid(),$txId,$no,$amount,$reason?:null,$u?(int)$u['id']:null]);return (int)db()->lastInsertId();}
function v900_reconciliation_create(string $account,float $opening,float $system,float $gateway,string $notes=''): int {$no='REC-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$diff=round($system-$gateway,2);db()->prepare("INSERT INTO wallet_reconciliations_v900(tenant_id,reconciliation_no,account_key,period_start,period_end,opening_balance,system_total,gateway_total,difference_amount,status,notes,created_at) VALUES(?,?,?,DATE_SUB(NOW(),INTERVAL 1 DAY),NOW(),?,?,?,?, 'open',?,NOW())")->execute([v900_tid(),$no,$account,$opening,$system,$gateway,$diff,$notes?:null]);return (int)db()->lastInsertId();}

function v900_gateway(?int $id=null): ?array {$rows=v900_rows('payment_gateways_v900','enabled=1',[],'is_default DESC,id DESC',50);if($id)foreach($rows as $r)if((int)$r['id']===$id)return $r;return $rows[0]??null;}
function v900_tx_upsert(int $gatewayId,string $externalRef,float $amount,string $currency,string $status,array $meta=[]): int {$q=db()->prepare('SELECT id FROM payment_transactions_v900 WHERE tenant_id=? AND gateway_id=? AND external_ref=? ORDER BY id DESC LIMIT 1');$q->execute([v900_tid(),$gatewayId,$externalRef]);$id=(int)($q->fetchColumn()?:0);if($id){db()->prepare('UPDATE payment_transactions_v900 SET amount=?,currency=?,status=?,meta_json=?,paid_at=IF(?=\'paid\',COALESCE(paid_at,NOW()),paid_at),updated_at=NOW() WHERE id=?')->execute([$amount,$currency,$status,json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$status,$id]);}else{$no='TX-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));db()->prepare('INSERT INTO payment_transactions_v900(tenant_id,gateway_id,transaction_no,external_ref,amount,currency,status,meta_json,paid_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,IF(?=\'paid\',NOW(),NULL),NOW(),NOW())')->execute([v900_tid(),$gatewayId,$no,$externalRef,$amount,$currency,$status,json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$status]);$id=(int)db()->lastInsertId();}if($status==='paid')v900_emit_event('payment.paid','payment_transaction',$id,['amount'=>$amount,'currency'=>$currency]);return $id;}
function v900_commission(string $module,float $gross,?string $payeeType=null): float {$rules=v900_rows('commission_rules_v900','module_key=? AND enabled=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW())',[$module],'priority ASC,id ASC',100);foreach($rules as $r){if($r['payee_type']&&$payeeType&&$r['payee_type']!==$payeeType)continue;$v=(float)$r['rate_value'];$fee=$r['rule_type']==='fixed'?$v:$gross*$v/100;if($r['minimum_amount']!==null)$fee=max($fee,(float)$r['minimum_amount']);if($r['maximum_amount']!==null)$fee=min($fee,(float)$r['maximum_amount']);return round(max(0,$fee),2);}return 0;}
function v900_invoice_create(string $billType,?int $billId,string $name,array $items,?string $dueDate=null): int {$subtotal=0;foreach($items as $i)$subtotal+=(float)($i['amount']??0);$no='INV-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));db()->prepare("INSERT INTO billing_invoices_v900(tenant_id,invoice_no,bill_to_type,bill_to_id,bill_to_name,subtotal,total_amount,status,due_date,items_json,issued_at,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'issued',?,?,NOW(),?,NOW(),NOW())")->execute([v900_tid(),$no,$billType,$billId,$name,$subtotal,$subtotal,$dueDate,json_encode($items,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),v900_user()['id']??null]);return (int)db()->lastInsertId();}

function v900_kyc_private_dir(): string {$d=dirname(__DIR__).'/storage/kyc-v900/'.v900_tid();if(!is_dir($d)&&!@mkdir($d,0700,true)&&!is_dir($d))throw new RuntimeException('Private KYC storage directory cannot be created.');return $d;}
function v900_kyc_store_upload(int $profileId,string $docType,array $file,?string $expires=null): int {if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Document upload failed.');$size=(int)($file['size']??0);if($size<1||$size>15*1024*1024)throw new RuntimeException('Document must be between 1 byte and 15 MB.');$tmp=(string)$file['tmp_name'];$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$finfo->file($tmp);$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??'';if($ext==='')throw new RuntimeException('Only PDF, JPG and PNG verification documents are accepted.');$name=bin2hex(random_bytes(20)).'.'.$ext;$path=v900_kyc_private_dir().'/'.$name;if(!@move_uploaded_file($tmp,$path)&&!@rename($tmp,$path))throw new RuntimeException('Unable to move document into private storage.');@chmod($path,0600);$hash=hash_file('sha256',$path);$u=v900_user();db()->prepare('INSERT INTO kyc_documents_v900(tenant_id,profile_id,document_type,document_label,storage_path,original_name,mime_type,file_size,sha256_hash,status,expires_at,uploaded_by,uploaded_at) VALUES(?,?,?,?,?,?,?,?,?,\'pending\',?,?,NOW())')->execute([v900_tid(),$profileId,$docType,v900_clip((string)($file['name']??$docType),190),$path,v900_clip((string)($file['name']??''),255),$mime,$size,$hash,$expires?:null,$u?(int)$u['id']:null]);$id=(int)db()->lastInsertId();v900_audit('kyc','document_uploaded','Private verification document uploaded.','medium','kyc_document',$id,['profile_id'=>$profileId,'type'=>$docType,'sha256'=>$hash]);return $id;}
function v900_identity_hash(string $value): array {$n=preg_replace('/\D+/','',$value);if(strlen($n)<5)return [null,null];$mask=str_repeat('•',max(0,strlen($n)-4)).substr($n,-4);return [hash('sha256',v900_tid().'|'.$n),$mask];}
function v900_kyc_review(int $profileId,string $status,string $notes='',?int $docId=null): void {if(!in_array($status,['pending','under_review','approved','rejected','expired'],true))throw new RuntimeException('Invalid KYC status.');$q=db()->prepare('SELECT status FROM kyc_profiles_v900 WHERE tenant_id=? AND id=? LIMIT 1');$q->execute([v900_tid(),$profileId]);$from=(string)($q->fetchColumn()?:'pending');$u=v900_user();db()->prepare('UPDATE kyc_profiles_v900 SET status=?,approved_at=IF(?=\'approved\',NOW(),approved_at),approved_by=IF(?=\'approved\',?,approved_by),rejection_reason=IF(?=\'rejected\',?,rejection_reason),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$status,$status,$status,$u?(int)$u['id']:null,$status,$notes,v900_tid(),$profileId]);if($docId)db()->prepare('UPDATE kyc_documents_v900 SET status=?,reviewed_by=?,reviewed_at=NOW(),review_notes=? WHERE tenant_id=? AND id=? AND profile_id=?')->execute([$status,$u?(int)$u['id']:null,$notes,v900_tid(),$docId,$profileId]);db()->prepare('INSERT INTO kyc_review_history_v900(tenant_id,profile_id,document_id,action_key,from_status,to_status,notes,actor_user_id,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())')->execute([v900_tid(),$profileId,$docId,'review',$from,$status,$notes,$u?(int)$u['id']:null]);v900_emit_event('kyc.'.$status,'kyc_profile',$profileId,['from'=>$from,'to'=>$status]);v900_audit('kyc','review','KYC status changed '.$from.' → '.$status.'.','high','kyc_profile',$profileId);}

function v900_emit_event(string $key,?string $entityType=null,?int $entityId=null,array $payload=[]): int {if(!v900_table('automation_events_v900'))return 0;db()->prepare('INSERT INTO automation_events_v900(tenant_id,event_key,entity_type,entity_id,payload_json,created_at) VALUES(?,?,?,?,?,NOW())')->execute([v900_tid(),$key,$entityType,$entityId,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$eid=(int)db()->lastInsertId();$workflows=v900_rows('automation_workflows_v900','enabled=1 AND trigger_type=\'module_event\' AND trigger_key=?',[$key],'id',100);foreach($workflows as $w)v900_workflow_queue((int)$w['id'],'module_event',['event_id'=>$eid,'event_key'=>$key,'entity_type'=>$entityType,'entity_id'=>$entityId,'payload'=>$payload]);return $eid;}
function v900_workflow_queue(int $workflowId,string $trigger='manual',array $payload=[]): int {db()->prepare("INSERT INTO automation_runs_v900(tenant_id,workflow_id,trigger_type,trigger_payload_json,status,created_at) VALUES(?,?,?,?,'queued',NOW())")->execute([v900_tid(),$workflowId,$trigger,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return (int)db()->lastInsertId();}
function v900_next_schedule(?string $expr): string {$expr=trim((string)$expr);$map=['hourly'=>'+1 hour','daily'=>'+1 day','weekly'=>'+1 week','monthly'=>'+1 month'];$delta=$map[$expr]??'+1 day';return date('Y-m-d H:i:s',strtotime($delta));}
function v900_schedule_workflows(int $limit=25): int {$n=0;$limit=max(1,min(50,$limit));if(!v900_table('automation_workflows_v900'))return 0;try{$rows=db()->query("SELECT * FROM automation_workflows_v900 WHERE enabled=1 AND trigger_type='schedule' AND (next_run_at IS NULL OR next_run_at<=NOW()) ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $w){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$w['tenant_id'];v900_workflow_queue((int)$w['id'],'schedule',[]);$next=v900_next_schedule((string)$w['schedule_expr']);db()->prepare('UPDATE automation_workflows_v900 SET next_run_at=?,last_run_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$next,(int)$w['id']]);$n++;}unset($GLOBALS['V900_TENANT_OVERRIDE']);}catch(Throwable $e){}return $n;}
function v900_ai_quota_ok(): bool {if(!v900_table('automation_ai_policies_v900'))return true;try{$q=db()->prepare('SELECT monthly_request_limit,monthly_cost_limit FROM automation_ai_policies_v900 WHERE tenant_id=? LIMIT 1');$q->execute([v900_tid()]);$p=$q->fetch();if(!$p)return true;$q=db()->prepare('SELECT COALESCE(SUM(requests),0),COALESCE(SUM(estimated_cost),0) FROM automation_ai_usage_v900 WHERE tenant_id=? AND usage_date>=DATE_FORMAT(CURDATE(),\'%Y-%m-01\')');$q->execute([v900_tid()]);[$req,$cost]=$q->fetch(PDO::FETCH_NUM)?:[0,0];return (int)$req<(int)$p['monthly_request_limit']&&(float)$cost<(float)$p['monthly_cost_limit'];}catch(Throwable $e){return true;}}
function v900_ai_usage(?int $agentId,?int $providerId,?int $workflowId,bool $ok,int $inTokens=0,int $outTokens=0,int $latency=0,float $cost=0): void {if(!v900_table('automation_ai_usage_v900'))return;try{db()->prepare('INSERT INTO automation_ai_usage_v900(tenant_id,usage_date,agent_id,provider_id,workflow_id,requests,input_tokens,output_tokens,estimated_cost,success_count,failure_count,latency_total_ms) VALUES(?,CURDATE(),?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE requests=requests+1,input_tokens=input_tokens+VALUES(input_tokens),output_tokens=output_tokens+VALUES(output_tokens),estimated_cost=estimated_cost+VALUES(estimated_cost),success_count=success_count+VALUES(success_count),failure_count=failure_count+VALUES(failure_count),latency_total_ms=latency_total_ms+VALUES(latency_total_ms)')->execute([v900_tid(),$agentId?:0,$providerId?:0,$workflowId?:0,1,$inTokens,$outTokens,$cost,$ok?1:0,$ok?0:1,$latency]);}catch(Throwable $e){} }
function v900_workflow_execute(array $run): string {$q=db()->prepare('SELECT * FROM automation_workflows_v900 WHERE id=? AND tenant_id=? AND enabled=1 LIMIT 1');$q->execute([(int)$run['workflow_id'],(int)$run['tenant_id']]);$w=$q->fetch();if(!$w)throw new RuntimeException('Workflow is unavailable.');$graph=v900_json($w['graph_json']??'');$nodes=$graph['nodes']??$graph;if(!is_array($nodes))throw new RuntimeException('Workflow graph is invalid.');$ctx=v900_json($run['output_json']??'');if(!$ctx)$ctx=['trigger'=>v900_json($run['trigger_payload_json']??''),'outputs'=>[],'_completed'=>[]];if(!isset($ctx['_completed'])||!is_array($ctx['_completed']))$ctx['_completed']=[];db()->prepare("UPDATE automation_runs_v900 SET status='running',started_at=COALESCE(started_at,NOW()) WHERE id=?")->execute([(int)$run['id']]);foreach($nodes as $idx=>$node){if(!is_array($node))continue;if(in_array((int)$idx,array_map('intval',$ctx['_completed']),true))continue;$type=(string)($node['type']??'noop');$label=(string)($node['label']??$type);db()->prepare('UPDATE automation_runs_v900 SET current_node=? WHERE id=?')->execute([$label,(int)$run['id']]);if($type==='condition'){continue;}if($type==='ai_generate'){if(!v900_ai_quota_ok())throw new RuntimeException('Tenant AI quota/cost limit reached.');if(!function_exists('ai710_chat'))throw new RuntimeException('AI v7.1 engine is unavailable.');$prompt=(string)($node['prompt']??'Summarize the workflow trigger and recommend the next safe action.');$t=microtime(true);try{$r=ai710_chat($prompt,null,isset($node['agent_id'])?(int)$node['agent_id']:null,'workflow-'.$run['id']);$ctx['outputs'][$idx]=$r['reply']??$r['text']??'';v900_ai_usage(isset($node['agent_id'])?(int)$node['agent_id']:null,isset($r['provider_id'])?(int)$r['provider_id']:null,(int)$w['id'],true,(int)($r['prompt_tokens']??0),(int)($r['completion_tokens']??0),(int)((microtime(true)-$t)*1000),(float)($r['estimated_cost']??0));}catch(Throwable $e){v900_ai_usage(isset($node['agent_id'])?(int)$node['agent_id']:null,null,(int)$w['id'],false,0,0,(int)((microtime(true)-$t)*1000),0);throw $e;}}
        elseif($type==='send_message'){$cid=(int)($node['conversation_id']??0);$body=(string)($node['body']??($ctx['outputs'][$idx-1]??''));if(!$cid||$body==='')throw new RuntimeException('Message workflow node needs conversation_id and body.');v900_comm_queue($cid,$body,isset($node['profile_id'])?(int)$node['profile_id']:null,null,!empty($node['ai_generated']));}
        elseif($type==='push'){$title=(string)($node['title']??'Notification');$body=(string)($node['body']??($ctx['outputs'][$idx-1]??''));v900_push_queue($title,$body,isset($node['user_id'])?(int)$node['user_id']:null,null,(string)($node['deep_link']??''));}
        elseif($type==='approval'){$qa=db()->prepare('SELECT * FROM automation_approvals_v900 WHERE tenant_id=? AND run_id=? AND node_index=? LIMIT 1');$qa->execute([v900_tid(),(int)$run['id'],(int)$idx]);$ap=$qa->fetch();if(!$ap){db()->prepare("INSERT INTO automation_approvals_v900(tenant_id,run_id,workflow_id,node_index,node_label,risk_level,status,requested_at) VALUES(?,?,?,?,?,'medium','pending',NOW())")->execute([v900_tid(),(int)$run['id'],(int)$w['id'],(int)$idx,$label]);db()->prepare("UPDATE automation_runs_v900 SET status='awaiting_approval',current_node=?,output_json=? WHERE id=?")->execute([$label,json_encode($ctx,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(int)$run['id']]);return 'Workflow paused for human approval.';}if((string)$ap['status']==='rejected')throw new RuntimeException('Workflow approval was rejected.');if((string)$ap['status']!=='approved'){db()->prepare("UPDATE automation_runs_v900 SET status='awaiting_approval',current_node=?,output_json=? WHERE id=?")->execute([$label,json_encode($ctx,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(int)$run['id']]);return 'Workflow is waiting for human approval.';}$ctx['outputs'][$idx]='approved';$ctx['human_approved']=true;}
        elseif($type==='webhook'){if(($w['approval_mode']??'safe_writes')!=='auto_low_risk'&&empty($ctx['human_approved']))throw new RuntimeException('External webhook node requires a preceding approved human checkpoint or an explicitly low-risk workflow policy.');$url=(string)($node['url']??'');v900_http($url,[],['workflow_id'=>(int)$w['id'],'run_id'=>(int)$run['id'],'context'=>$ctx]);}
        elseif($type==='report'){$ctx['outputs'][$idx]=v900_dashboard_stats();}
        $ctx['_completed'][]=(int)$idx;$ctx['_completed']=array_values(array_unique(array_map('intval',$ctx['_completed'])));db()->prepare('UPDATE automation_runs_v900 SET output_json=? WHERE id=?')->execute([json_encode($ctx,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(int)$run['id']]);
    }db()->prepare("UPDATE automation_runs_v900 SET status='completed',output_json=?,current_node=NULL,finished_at=NOW() WHERE id=?")->execute([json_encode($ctx,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(int)$run['id']]);return 'Workflow completed.';}

function v900_workflow_approval_decide(int $approvalId,bool $approve,string $notes=''): void {$q=db()->prepare('SELECT * FROM automation_approvals_v900 WHERE tenant_id=? AND id=? LIMIT 1');$q->execute([v900_tid(),$approvalId]);$a=$q->fetch();if(!$a)throw new RuntimeException('Workflow approval not found.');if($a['status']!=='pending')throw new RuntimeException('Workflow approval is already decided.');$u=v900_user();$status=$approve?'approved':'rejected';db()->prepare('UPDATE automation_approvals_v900 SET status=?,decided_by=?,decided_at=NOW(),decision_notes=? WHERE id=? AND tenant_id=?')->execute([$status,$u?(int)$u['id']:null,$notes?:null,$approvalId,v900_tid()]);db()->prepare('UPDATE automation_runs_v900 SET status=?,error_message=? WHERE id=? AND tenant_id=?')->execute([$approve?'queued':'failed',$approve?null:'Approval rejected: '.v900_clip($notes,700),(int)$a['run_id'],v900_tid()]);v900_audit('automation','approval_'.$status,'Workflow checkpoint '.$status.'.','high','automation_run',(int)$a['run_id']);}

function v900_accounting_post(array $lines,string $memo='',?string $referenceType=null,?int $referenceId=null): int {$debit=$credit=0;foreach($lines as $l){$debit+=(float)($l['debit']??0);$credit+=(float)($l['credit']??0);}if(abs($debit-$credit)>0.005||$debit<=0)throw new RuntimeException('Journal must be balanced with equal positive debit and credit totals.');$u=v900_user();$no='JRN-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));db()->beginTransaction();try{db()->prepare("INSERT INTO accounting_journals_v900(tenant_id,journal_no,journal_date,reference_type,reference_id,memo,status,total_debit,total_credit,created_by,created_at) VALUES(?,?,CURDATE(),?,?,?,'posted',?,?,?,NOW())")->execute([v900_tid(),$no,$referenceType,$referenceId,$memo,$debit,$credit,$u?(int)$u['id']:null]);$jid=(int)db()->lastInsertId();$st=db()->prepare('INSERT INTO accounting_journal_lines_v900(tenant_id,journal_id,account_id,description,debit,credit,entity_type,entity_id,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())');foreach($lines as $l)$st->execute([v900_tid(),$jid,(int)$l['account_id'],v900_clip((string)($l['description']??''),500),(float)($l['debit']??0),(float)($l['credit']??0),$l['entity_type']??null,$l['entity_id']??null]);db()->commit();v900_audit('accounting','journal_posted','Balanced journal '.$no.' posted.','high','journal',$jid,['debit'=>$debit,'credit'=>$credit]);return $jid;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
function v900_ticket_create(string $subject,string $description,string $priority='normal',?int $contactId=null): int {$priority=in_array($priority,['low','normal','high','urgent'],true)?$priority:'normal';$q=db()->prepare('SELECT * FROM sla_policies_v900 WHERE tenant_id=? AND enabled=1 AND priority=? ORDER BY id LIMIT 1');$q->execute([v900_tid(),$priority]);$sla=$q->fetch();$no='TKT-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$fr=$sla?'DATE_ADD(NOW(),INTERVAL '.(int)$sla['first_response_minutes'].' MINUTE)':'NULL';$rr=$sla?'DATE_ADD(NOW(),INTERVAL '.(int)$sla['resolution_minutes'].' MINUTE)':'NULL';db()->exec("INSERT INTO helpdesk_tickets_v900(tenant_id,ticket_no,contact_id,subject,description,priority,status,sla_policy_id,first_response_due_at,resolution_due_at,created_at,updated_at) VALUES(".v900_tid().','.db()->quote($no).','.($contactId?:'NULL').','.db()->quote(v900_clip($subject,255)).','.db()->quote(v900_clip($description,20000)).','.db()->quote($priority).",'open',".($sla?(int)$sla['id']:'NULL').",{$fr},{$rr},NOW(),NOW())");$id=(int)db()->lastInsertId();v900_emit_event('support.ticket.created','helpdesk_ticket',$id,['priority'=>$priority]);return $id;}
function v900_sla_sweep(): int {if(!v900_table('helpdesk_tickets_v900'))return 0;$n=0;try{$rows=db()->query("SELECT tenant_id,id,ticket_no,priority,first_response_due_at,resolution_due_at,first_responded_at,resolved_at FROM helpdesk_tickets_v900 WHERE status NOT IN ('resolved','closed') AND ((first_responded_at IS NULL AND first_response_due_at<NOW()) OR (resolved_at IS NULL AND resolution_due_at<NOW())) LIMIT 200")->fetchAll()?:[];foreach($rows as $r){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$r['tenant_id'];v900_realtime_emit('sla.breach',['ticket_id'=>(int)$r['id'],'ticket_no'=>$r['ticket_no'],'priority'=>$r['priority']],'admin');v900_audit('helpdesk','sla_breach','SLA breach detected for '.$r['ticket_no'].'.','medium','helpdesk_ticket',(int)$r['id']);$n++;}unset($GLOBALS['V900_TENANT_OVERRIDE']);}catch(Throwable $e){}return $n;}
function v900_kyc_expiry_sweep(): int {if(!v900_table('kyc_profiles_v900'))return 0;$n=0;try{$rows=db()->query("SELECT tenant_id,id,display_name,expires_at FROM kyc_profiles_v900 WHERE status='approved' AND expires_at IS NOT NULL AND expires_at<=DATE_ADD(CURDATE(),INTERVAL 30 DAY) LIMIT 200")->fetchAll()?:[];foreach($rows as $r){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$r['tenant_id'];v900_realtime_emit('kyc.expiry_due',['profile_id'=>(int)$r['id'],'name'=>$r['display_name'],'expires_at'=>$r['expires_at']],'admin');$n++;}unset($GLOBALS['V900_TENANT_OVERRIDE']);}catch(Throwable $e){}return $n;}
function v900_franchise_snapshot(): int {if(!v900_table('franchise_kpis_v900'))return 0;$n=0;try{$tenants=[v900_tid()];if(v900_tid()===0&&v900_table('tenants')){$cols=v900_cols('tenants');if(isset($cols['id']))$tenants=array_map('intval',db()->query('SELECT id FROM tenants ORDER BY id')->fetchAll(PDO::FETCH_COLUMN)?:[0]);}foreach($tenants as $tid){$GLOBALS['V900_TENANT_OVERRIDE']=$tid;$s=v900_dashboard_stats();foreach(['devices','messages_30d','kyc_pending','tickets_open','workflow_runs_30d'] as $k){db()->prepare('INSERT INTO franchise_kpis_v900(tenant_id,snapshot_date,metric_key,metric_value,created_at) VALUES(?,CURDATE(),?,?,NOW()) ON DUPLICATE KEY UPDATE metric_value=VALUES(metric_value)')->execute([$tid,$k,(float)$s[$k]]);$n++;}}unset($GLOBALS['V900_TENANT_OVERRIDE']);}catch(Throwable $e){}return $n;}

function v900_worker_run(int $limit=25): array {$limit=max(1,min(50,$limit));$result=['campaigns'=>0,'push'=>0,'messages'=>0,'workflows'=>0,'content'=>0,'failed'=>0,'scheduled'=>v900_schedule_workflows($limit),'sla'=>0,'kyc_reminders'=>0,'kpis'=>0];
    if(v900_table('comm_campaigns_v900')){try{$rows=db()->query("SELECT * FROM comm_campaigns_v900 WHERE status='scheduled' AND (schedule_at IS NULL OR schedule_at<=NOW()) ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $c){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$c['tenant_id'];try{v900_campaign_expand($c);$result['campaigns']++;}catch(Throwable $e){db()->prepare("UPDATE comm_campaigns_v900 SET status='failed',updated_at=NOW() WHERE id=?")->execute([(int)$c['id']]);$result['failed']++;}}}catch(Throwable $e){}}
    if(v900_table('mobile_push_queue_v900')){try{$rows=db()->query("SELECT * FROM mobile_push_queue_v900 WHERE status IN ('pending','retry') AND available_at<=NOW() ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $r){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$r['tenant_id'];try{$id=v900_push_send_row($r);db()->prepare("UPDATE mobile_push_queue_v900 SET status='sent',provider_message_id=?,sent_at=NOW(),attempts=attempts+1,last_error=NULL,updated_at=NOW() WHERE id=?")->execute([$id,(int)$r['id']]);$result['push']++;}catch(Throwable $e){$a=(int)$r['attempts']+1;$st=$a>=5?'failed':'retry';db()->prepare('UPDATE mobile_push_queue_v900 SET status=?,attempts=?,last_error=?,available_at=DATE_ADD(NOW(),INTERVAL ? SECOND),updated_at=NOW() WHERE id=?')->execute([$st,$a,v900_clip($e->getMessage(),1000),min(3600,30*(2**min(6,$a))),(int)$r['id']]);$result['failed']++;}}}catch(Throwable $e){}}
    if(v900_table('comm_messages_v900')){try{$rows=db()->query("SELECT * FROM comm_messages_v900 WHERE direction='outbound' AND status='queued' ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $m){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$m['tenant_id'];try{$ext=v900_comm_send_row($m);db()->prepare("UPDATE comm_messages_v900 SET status='sent',external_message_id=?,sent_at=NOW(),last_error=NULL,updated_at=NOW() WHERE id=?")->execute([$ext,(int)$m['id']]);$result['messages']++;}catch(Throwable $e){db()->prepare("UPDATE comm_messages_v900 SET status='failed',failed_at=NOW(),last_error=?,updated_at=NOW() WHERE id=?")->execute([v900_clip($e->getMessage(),1000),(int)$m['id']]);$result['failed']++;}}}catch(Throwable $e){}}
    if(v900_table('automation_runs_v900')){try{$rows=db()->query("SELECT * FROM automation_runs_v900 WHERE status='queued' ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $r){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$r['tenant_id'];try{v900_workflow_execute($r);$result['workflows']++;}catch(Throwable $e){db()->prepare("UPDATE automation_runs_v900 SET status='failed',error_message=?,finished_at=NOW() WHERE id=?")->execute([v900_clip($e->getMessage(),1000),(int)$r['id']]);$result['failed']++;}}}catch(Throwable $e){}}
    if(v900_table('automation_content_jobs_v900')&&function_exists('ai710_chat')){try{$rows=db()->query("SELECT * FROM automation_content_jobs_v900 WHERE status='queued' ORDER BY id LIMIT {$limit}")->fetchAll()?:[];foreach($rows as $r){$GLOBALS['V900_TENANT_OVERRIDE']=(int)$r['tenant_id'];try{if(!v900_ai_quota_ok())throw new RuntimeException('Tenant AI quota/cost limit reached.');$res=ai710_chat((string)$r['prompt_text'],null,$r['agent_id']?(int)$r['agent_id']:null,'content-job-'.$r['id']);$out=(string)($res['reply']??$res['text']??'');$status=!empty($r['approval_required'])?'awaiting_approval':'completed';db()->prepare('UPDATE automation_content_jobs_v900 SET output_text=?,status=?,updated_at=NOW() WHERE id=?')->execute([$out,$status,(int)$r['id']]);$result['content']++;}catch(Throwable $e){db()->prepare("UPDATE automation_content_jobs_v900 SET status='failed',error_message=?,updated_at=NOW() WHERE id=?")->execute([v900_clip($e->getMessage(),1000),(int)$r['id']]);$result['failed']++;}}}catch(Throwable $e){}}
    if(v900_table('comm_campaigns_v900')){try{db()->exec("UPDATE comm_campaigns_v900 c SET c.sent_count=(SELECT COUNT(*) FROM comm_messages_v900 m JOIN comm_conversations_v900 x ON x.id=m.conversation_id WHERE x.tenant_id=c.tenant_id AND m.campaign_id=c.id AND m.status IN ('sent','delivered','read')),c.delivered_count=(SELECT COUNT(*) FROM comm_messages_v900 m JOIN comm_conversations_v900 x ON x.id=m.conversation_id WHERE x.tenant_id=c.tenant_id AND m.campaign_id=c.id AND m.status IN ('delivered','read')),c.read_count=(SELECT COUNT(*) FROM comm_messages_v900 m JOIN comm_conversations_v900 x ON x.id=m.conversation_id WHERE x.tenant_id=c.tenant_id AND m.campaign_id=c.id AND m.status='read'),c.failed_count=(SELECT COUNT(*) FROM comm_messages_v900 m JOIN comm_conversations_v900 x ON x.id=m.conversation_id WHERE x.tenant_id=c.tenant_id AND m.campaign_id=c.id AND m.status='failed'),c.status=IF(c.total_count>0 AND (c.sent_count+c.failed_count)>=c.total_count,'completed',c.status) WHERE c.status='processing'");}catch(Throwable $e){}}
    unset($GLOBALS['V900_TENANT_OVERRIDE']);
    // v9.0.1: expensive periodic sweeps are throttled. The v9.0.0 worker ran
    // SLA/KYC sweeps every minute and franchise snapshots during the first five
    // minutes of every hour. On shared hosting this can create avoidable DB load.
    $minute=(int)date('i');$hour=(int)date('G');
    if($minute%15===0)$result['sla']=v900_sla_sweep();
    if($hour===8&&$minute<5)$result['kyc_reminders']=v900_kyc_expiry_sweep();
    if($hour===2&&$minute<5)$result['kpis']=v900_franchise_snapshot();
    return $result;}
